Below is a small Node.js app. Files and password hashes stay on the server; the download endpoint checks the password before sending any file data.

### 1. Install dependencies

```bash
mkdir file-share && cd file-share
npm init -y
npm install express multer bcrypt express-rate-limit
```

### 2. Create `server.js`

```js
const express = require("express");
const multer = require("multer");
const bcrypt = require("bcrypt");
const crypto = require("crypto");
const fs = require("fs/promises");
const path = require("path");
const { rateLimit } = require("express-rate-limit");

const app = express();
const DATA_DIR = path.join(__dirname, "private-data");
const TEMP_DIR = path.join(DATA_DIR, "temp");

// Never serve DATA_DIR with express.static().
const upload = multer({
  dest: TEMP_DIR,
  limits: { fileSize: 100 * 1024 * 1024, files: 1 } // 100 MB
});

app.use(express.urlencoded({ extended: false, limit: "4kb" }));

const downloadLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 30,
  standardHeaders: "draft-7",
  legacyHeaders: false,
  message: "Too many attempts. Please try again later."
});

function validPassword(password) {
  // bcrypt only uses the first 72 UTF-8 bytes.
  return typeof password === "string" &&
    Buffer.byteLength(password, "utf8") >= 8 &&
    Buffer.byteLength(password, "utf8") <= 72;
}

function validToken(token) {
  return /^[a-f0-9]{64}$/.test(token);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${title}</title>
  <style>
    body { font: 16px system-ui; max-width: 36rem; margin: 3rem auto;
           padding: 0 1rem; line-height: 1.5; }
    label, input, button { display: block; margin: 0.7rem 0; }
    input, button { font: inherit; }
    button { padding: 0.5rem 1rem; cursor: pointer; }
  </style>
</head>
<body>${content}</body>
</html>`;
}

app.get("/", (req, res) => {
  res.send(page("Share a file", `
    <h1>Share a file</h1>
    <p>Choose a file and a password. Maximum file size: 100 MB.</p>
    <form action="/upload" method="post" enctype="multipart/form-data">
      <label>File <input type="file" name="file" required></label>
      <label>Password
        <input type="password" name="password" required
               minlength="8" autocomplete="new-password">
      </label>
      <button type="submit">Upload</button>
    </form>
  `));
});

app.post("/upload", upload.single("file"), async (req, res) => {
  let targetDir;

  try {
    if (!req.file || !validPassword(req.body.password)) {
      if (req.file) await fs.rm(req.file.path, { force: true });
      return res.status(400).send(
        "Choose a file and a password of 8 to 72 UTF-8 bytes."
      );
    }

    const token = crypto.randomBytes(32).toString("hex");
    const hash = await bcrypt.hash(req.body.password, 12);
    targetDir = path.join(DATA_DIR, token);

    await fs.mkdir(targetDir);
    await fs.rename(req.file.path, path.join(targetDir, "file"));
    await fs.writeFile(
      path.join(targetDir, "metadata.json"),
      JSON.stringify({ hash, filename: req.file.originalname }),
      { mode: 0o600 }
    );

    // A relative link avoids trusting the request's Host header.
    res.send(page("File uploaded", `
      <h1>File uploaded</h1>
      <p>Share this link with your friends, and send the password separately:</p>
      <p><a href="/s/${token}">Open share link</a></p>
      <p>Copy the address from the link above.</p>
      <p><a href="/">Upload another file</a></p>
    `));
  } catch (err) {
    console.error(err);
    if (req.file) await fs.rm(req.file.path, { force: true }).catch(() => {});
    if (targetDir) {
      await fs.rm(targetDir, { recursive: true, force: true }).catch(() => {});
    }
    res.status(500).send("Upload failed.");
  }
});

app.get("/s/:token", (req, res) => {
  if (!validToken(req.params.token)) return res.sendStatus(404);

  res.set("Cache-Control", "no-store");
  res.send(page("Download file", `
    <h1>Download file</h1>
    <form action="/s/${req.params.token}/download" method="post">
      <label>Password
        <input type="password" name="password" required
               autocomplete="current-password">
      </label>
      <button type="submit">Download</button>
    </form>
  `));
});

app.post("/s/:token/download", downloadLimiter, async (req, res) => {
  const { token } = req.params;
  if (!validToken(token) || !validPassword(req.body.password)) {
    return res.status(400).send("Invalid request.");
  }

  try {
    const dir = path.join(DATA_DIR, token);
    const metadata = JSON.parse(
      await fs.readFile(path.join(dir, "metadata.json"), "utf8")
    );

    if (!(await bcrypt.compare(req.body.password, metadata.hash))) {
      return res.status(403).send("Incorrect password.");
    }

    res.set("Cache-Control", "no-store");
    res.set("X-Content-Type-Options", "nosniff");
    res.download(path.join(dir, "file"), metadata.filename, err => {
      if (err) {
        console.error(err);
        if (!res.headersSent) res.status(500).send("Download failed.");
      }
    });
  } catch (err) {
    if (err.code === "ENOENT") return res.sendStatus(404);
    console.error(err);
    res.status(500).send("Download failed.");
  }
});

app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    return res.status(400).send(`Upload error: ${err.message}`);
  }
  console.error(err);
  res.status(500).send("Something went wrong.");
});

fs.mkdir(TEMP_DIR, { recursive: true, mode: 0o700 }).then(() => {
  app.listen(3000, () => console.log("Open http://localhost:3000"));
}).catch(console.error);
```

### 3. Run it

```bash
node server.js
```

Open `http://localhost:3000`, upload a file, and share the resulting link.

**Before exposing this publicly:** use HTTPS so passwords and files are encrypted in transit, and configure your hosting or reverse proxy so `private-data` is never publicly served. This example keeps files indefinitely; add deletion, storage quotas, and upload rate limits for a production service.

